{"command":["bash","-lc","python3 - <<'PY'
import json, pathlib, collections, sys
alerts_dir = pathlib.Path('alerts')
all_alerts = []
for p in alerts_dir.glob('*.json'):
    try:
        data = json.loads(p.read_text())
        if isinstance(data, list):
            all_alerts.extend(data)
        else:
            print('unexpected format', p, file=sys.stderr)
    except Exception as e:
        print('err', p, e, file=sys.stderr)

# Filter otel-demo namespace alerts
ns_alerts = [a for a in all_alerts if a.get('labels',{}).get('namespace')=='otel-demo']
print('Total alerts', len(all_alerts), 'otel-demo', len(ns_alerts))
# summary by alertname/state
summary = collections.Counter()
for a in ns_alerts:
    name = a.get('labels',{}).get('alertname','<none>')
    state = a.get('state','unknown')
    summary[(name,state)] += 1
for (name,state),cnt in summary.most_common():
    print(name, state, cnt)
PY"],"timeout_ms":100000,"workdir":"/root/projects/open_source/zero/B96DF826-4BB2-4B62-97AB-6D84254C53D7/Scenario-81"}

